const URL_TSE='https://resultados.tse.jus.br/oficial/ele2026/6258/dados/br/br-c0001-e006258-u.json';
const $=id=>document.getElementById(id),fmt=n=>Math.round(n).toLocaleString('pt-BR'),pct=n=>n.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})+'%',esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let mode='demo',history=[],liveHistory=[],liveNames=null,names=[],timer=null,busy=false,epoch=0;
function resetDemo(){history=[FirstTurn.snapshot(FIRST_TURN_DATA.national,5),FirstTurn.snapshot(FIRST_TURN_DATA.national,10)];names=FirstTurn.pairNames(FIRST_TURN_DATA.national);window.dispatchEvent(new Event('horizonte-demo-reset'));render();}
function notice(msg,error=false){$('notice').textContent=msg;$('notice').classList.toggle('error',error);}
function render(){
 const cur=history.at(-1),method=$('method').value,proj=ElectionModel.project(history,method),sum=cur?cur.a+cur.b:0,projectedTotal=proj?proj[0]+proj[1]:0;
 $('progress').textContent=pct(cur?.p||0);$('progressbar').style.width=(cur?.p||0)+'%';$('votes').textContent=fmt(sum);
 $('sections').textContent=mode==='official'&&cur?.total?`${fmt(cur.counted)} de ${fmt(cur.total)} seções`:mode==='demo'?'Etapa simulada com a base do 1º turno':'Aguardando seções do TSE';
 $('updated').textContent=cur?(mode==='demo'?cur.label:cur.label+' · '+cur.date):'Aguardando consulta';$('status').textContent=mode==='demo'?'1º turno real · avanço proporcional simulado':cur?.p===0?'Apuração ainda não iniciada':cur?.p===100?'100% das seções totalizadas':'Última leitura oficial recebida';
 $('cards').innerHTML=[0,1].map((i)=>{const votes=cur?(i===0?cur.a:cur.b):0;const share=sum?votes/sum*100:0;return `<div class="candidate ${i?'b':''}"><div class="candidateTop"><div class="identity"><img class="candidatePhoto" src="photos/${esc(names[i]?.id||'unknown')}.jpeg" alt="Foto de ${esc(names[i]?.name||'candidato')}" width="48" height="48"><div><div class="name">${esc(names[i]?.name||'Aguardando TSE')}</div><div class="sub">${esc(names[i]?.party||'')} · ${fmt(votes)} votos</div></div></div><div class="pct">${sum?pct(share):'—'}</div></div><div class="bar"><i style="width:${share}%"></i></div><div class="metrics"><span>Entre os dois candidatos</span><span>Em 100%: <b>${projectedTotal?pct(proj[i]/projectedTotal*100)+' · '+fmt(proj[i])+' votos':'aguardando dados'}</b></span></div></div>`}).join('');
 if(projectedTotal){const winner=proj[0]===proj[1]?-1:proj[0]>proj[1]?0:1;$('headline').textContent=winner<0?'Empate no cenário projetado':`${names[winner]?.name||'Candidato'}: ${pct(proj[winner]/projectedTotal*100)} entre os dois`;$('explanation').textContent=cur.p===100?mode==='demo'?'Etapa completa da reprodução proporcional. Não é uma simulação de transferência de votos para o 2º turno.':'Contagem observada com 100% das seções, sem extrapolação.':`${method==='recent'?'Mantido o ritmo da janela recente':'Mantida a média acumulada'} · diferença projetada de ${fmt(Math.abs(proj[0]-proj[1]))} votos.`;}else{$('headline').textContent='Aguardando base para projetar';$('explanation').textContent=cur?.p>0?'O ritmo recente precisa de duas leituras com avanço na apuração.':'A projeção começa após a entrada dos primeiros votos.';}
 $('history').innerHTML=history.map((h,i)=>{const prev=history[i-1],delta=prev?(h.a+h.b-prev.a-prev.b):0,pr=ElectionModel.project(history.slice(0,i+1),method);return `<tr><td>${esc(h.label)}</td><td>${pct(h.p)}</td><td>${fmt(h.a)}</td><td>${fmt(h.b)}</td><td>${delta>0?pct((h.a-prev.a)/delta*100):'—'}</td><td>${pr&&pr[0]+pr[1]>0?pct(pr[0]/(pr[0]+pr[1])*100):'—'}</td></tr>`}).reverse().slice(0,30).join('');
 window.dispatchEvent(new CustomEvent('horizonte-reading',{detail:{mode,cur}}));drawChart(method);$('advance').disabled=cur?.p>=100;
 if(mode==='demo')notice('DEMONSTRAÇÃO COM 1º TURNO · Votos reais de 2026, distribuídos proporcionalmente em etapas simuladas. Os percentuais dos candidatos comparam apenas Lula e Flávio; não são o resultado completo do 1º turno nem uma previsão do 2º.');
}
function drawChart(method){const points=history.map((h,i)=>{const pr=ElectionModel.project(history.slice(0,i+1),method);return pr&&pr[0]+pr[1]>0?{x:48+h.p*8.9,y:140-pr[0]/(pr[0]+pr[1])*120}:null}).filter(Boolean);$('chart').innerHTML=`<svg viewBox="0 0 960 175" role="img" aria-label="Participação projetada de Lula entre os dois, de zero a cem por cento, conforme avança a apuração"><line x1="48" y1="80" x2="938" y2="80" stroke="#acb8aa" stroke-dasharray="5 6"/><line x1="48" y1="140" x2="938" y2="140" stroke="#e5e9e0"/><text x="5" y="24" font-size="11" fill="#66776c">100%</text><text x="12" y="84" font-size="11" fill="#66776c">50%</text><text x="20" y="144" font-size="11" fill="#66776c">0%</text><text x="48" y="167" font-size="11" fill="#66776c">0% apurado</text><text x="850" y="167" font-size="11" fill="#66776c">100% apurado</text><polyline points="${points.map(p=>p.x+','+p.y).join(' ')}" fill="none" stroke="#1e654e" stroke-width="3"/>${points.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="4" fill="#1e654e"/>`).join('')}${points.length?'':'<text x="330" y="56" font-size="13" fill="#66776c">Aguardando leituras para traçar a projeção</text>'}</svg>`;}
function stopAuto(){clearInterval(timer);timer=null;$('auto').checked=false;}function startAuto(){if(timer)return;$('auto').checked=true;timer=setInterval(fetchOfficial,60000);}
async function fetchOfficial(){if(busy||mode!=='official')return;busy=true;$('refresh').disabled=true;const requestEpoch=epoch;try{notice('Carregando a leitura compartilhada do projeto…');const response=await fetch(URL_TSE,{cache:'no-cache',signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error(`Snapshot do projeto respondeu HTTP ${response.status}. Nova tentativa automática em até um minuto.`);const snap=ElectionModel.parseTSE(await response.json());if(mode!=='official'||requestEpoch!==epoch)return;const prev=liveHistory.at(-1);let correction=false;
 if(prev&&snap.timestamp<prev.timestamp)throw Error('O projeto retornou uma versão anterior. Última leitura preservada.');
 if(!prev||snap.id!==prev.id){if(prev&&(snap.a<prev.a||snap.b<prev.b||snap.counted<prev.counted||snap.total!==prev.total||snap.candidates.some((c,i)=>c.id!==prev.candidates[i].id))){liveHistory=[];correction=true;}if(!prev||snap.a!==prev.a||snap.b!==prev.b||snap.counted!==prev.counted||correction)liveHistory.push(snap);else liveHistory[liveHistory.length-1]=snap;}
 liveNames=snap.candidates;names=liveNames;history=liveHistory;render();notice(`DADOS OFICIAIS · Arquivo do TSE gerado em ${snap.date} às ${snap.label} (Brasília). ${correction?'Correção detectada: janela de projeção reiniciada.':snap.p===0?'Aguardando o início da apuração.':'Projeções calculadas por este painel, não pelo TSE.'}`);if(snap.p===100)stopAuto();
 }catch(err){if(mode==='official'&&requestEpoch===epoch){notice(`Não foi possível atualizar: ${err.message}. ${liveHistory.length?'Os dados anteriores foram mantidos.':'Nenhum dado oficial carregado.'} O arquivo compartilhado do projeto está indisponível.`,true);}}finally{busy=false;$('refresh').disabled=false;}}
function setMode(next){epoch++;stopAuto();mode=next;window.dispatchEvent(new CustomEvent('horizonte-mode',{detail:next}));for(const id of ['demo','official']){$(id).classList.toggle('active',id===next);$(id).setAttribute('aria-pressed',String(id===next));}$('simulator').hidden=next!=='demo';$('liveControls').hidden=next!=='official';if(next==='demo')resetDemo();else{const generation=epoch;window.TSEClient.history().then(shared=>{if(mode!=='official'||generation!==epoch)return;liveHistory=shared.national||[];history=liveHistory;liveNames=liveHistory.at(-1)?.candidates||null;names=liveNames||[];render();fetchOfficial();startAuto();}).catch(()=>{history=liveHistory;names=liveNames||[];render();fetchOfficial();startAuto();});}}
$('demo').onclick=()=>setMode('demo');$('official').onclick=()=>setMode('official');$('reset').onclick=resetDemo;$('method').onchange=render;$('share').oninput=()=>$('shareLabel').textContent=$('share').value+'%';$('advance').onclick=()=>{const cur=history.at(-1),step=Math.min(Number($('step').value),100-cur.p);if(step<=0)return;window.dispatchEvent(new CustomEvent('horizonte-demo-advance',{detail:step}));};$('refresh').onclick=fetchOfficial;$('auto').onchange=()=>{if($('auto').checked){fetchOfficial();startAuto();}else stopAuto();};$('source').href=URL_TSE;
$('export').onclick=()=>{const data={mode,election:'2026-presidente-segundo-turno',source:mode==='official'?URL_TSE:FIRST_TURN_DATA.source,demonstration:mode==='demo'?'Avanço proporcional simulado do primeiro turno; comparação restrita a Lula e Flávio':null,method:$('method').value,candidates:names,exportedAt:new Date().toISOString(),history};const link=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));link.href=url;link.download=`painel-eleitoral-2026-${mode}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};window.addEventListener('horizonte-demo-snapshot',e=>{if(mode==='demo'){history=e.detail;render();}});resetDemo();



